import * as THREE from './assets/three.module.js';
export function addTVSideSlats(parent){const group=new THREE.Group();group.name='tv-walnut-side-slats';group.userData={finish:'Dark brown walnut',zones:[[.35,.95],[3.55,4.15]],centerUnpanelled:true};parent.add(group);
 const canvas=document.createElement('canvas');canvas.width=128;canvas.height=512;const ctx=canvas.getContext('2d');ctx.fillStyle='#513a2b';ctx.fillRect(0,0,128,512);for(let i=0;i<128;i++){ctx.strokeStyle=i%3?'rgba(180,130,86,.18)':'rgba(24,17,12,.25)';ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(i,0);ctx.bezierCurveTo(i+2,170,i-2,340,i,512);ctx.stroke();}const map=new THREE.CanvasTexture(canvas);map.colorSpace=THREE.SRGBColorSpace;
 const walnut=new THREE.MeshStandardMaterial({map,roughness:.83,bumpMap:map,bumpScale:.001}),felt=new THREE.MeshStandardMaterial({color:'#302820',roughness:1}),metal=new THREE.MeshStandardMaterial({color:'#534338',metalness:.6,roughness:.38}),glow=new THREE.MeshStandardMaterial({color:'#ffe5b9',emissive:'#ffd49b',emissiveIntensity:1.3});const lights=[];
 for(const [index,[a,b]]of group.userData.zones.entries()){const zone=new THREE.Group();zone.name=index?'tv-left-walnut-panel':'tv-right-walnut-panel';group.add(zone);const backing=new THREE.Mesh(new THREE.BoxGeometry(.015,2.70,b-a),felt);backing.position.set(5.3875,1.35,(a+b)/2);backing.receiveShadow=true;zone.add(backing);
  const count=12,ribs=new THREE.InstancedMesh(new THREE.BoxGeometry(.035,2.70,.028),walnut,count),matrix=new THREE.Matrix4();for(let i=0;i<count;i++){matrix.makeTranslation(5.3575,1.35,a+.025+i*(b-a-.05)/(count-1));ribs.setMatrixAt(i,matrix);}ribs.castShadow=ribs.receiveShadow=true;zone.add(ribs);
  const sconce=new THREE.Group();sconce.name=index?'tv-left-wall-sconce':'tv-right-wall-sconce';sconce.position.set(5.285,2.49,(a+b)/2);group.add(sconce);
  const plate=new THREE.Mesh(new THREE.BoxGeometry(.025,.16,.085),metal);plate.position.x=.055;sconce.add(plate);const body=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.26,20,1,true),metal);body.castShadow=true;sconce.add(body);for(const side of[-1,1]){const end=new THREE.Mesh(new THREE.CircleGeometry(.029,20),glow);end.rotation.x=side>0?-Math.PI/2:Math.PI/2;end.position.y=side*.129;sconce.add(end);}
  const light=new THREE.PointLight('#ffdfad',.8,2.4,2);light.position.set(5.15,2.48,(a+b)/2);light.userData.livingWallSconce=true;group.add(light);lights.push(light);
 }return {group,lights};}
